<?php
declare(strict_types=1);namespace App\Services;use App\Security\DeviceCredentialCipher;use PDO;use RuntimeException;
final readonly class NodeRtmpService{public function __construct(private PDO $db,private DeviceCredentialCipher $cipher){}public function pending(int $server):?array{$s=$this->db->prepare('SELECT * FROM rtmp_ingest_configs WHERE server_id=? AND desired_version>applied_version AND status IN (\'pending\',\'failed\')');$s->execute([$server]);$c=$s->fetch();if(!$c)return null;$ips=$this->db->prepare('SELECT ip FROM rtmp_ingest_ips WHERE config_id=? ORDER BY ip');$ips->execute([$c['id']]);$this->db->prepare("UPDATE rtmp_ingest_configs SET status='applying',last_error=NULL WHERE id=?")->execute([$c['id']]);return ['config_id'=>(int)$c['id'],'version'=>(int)$c['desired_version'],'enabled'=>(bool)$c['enabled'],'port'=>(int)$c['port'],'application'=>$c['application_name'],'publish_key'=>$this->cipher->decrypt($c['publish_key_ciphertext']),'allowed_ips'=>$ips->fetchAll(PDO::FETCH_COLUMN)];}public function result(int $server,int $id,int $version,bool $success,?string $error):void{$s=$this->db->prepare('SELECT desired_version,enabled FROM rtmp_ingest_configs WHERE id=? AND server_id=?');$s->execute([$id,$server]);$config=$s->fetch();if(!$config||(int)$config['desired_version']!==$version)throw new RuntimeException('Versión RTMP obsoleta o inválida.');$status=$success?((int)$config['enabled']===1?'active':'disabled'):'failed';$this->db->prepare("UPDATE rtmp_ingest_configs SET status=?,applied_version=IF(?, ?, applied_version),last_error=? WHERE id=?")->execute([$status,$success,$version,$success?null:substr((string)$error,0,65535),$id]);}}
